  this.ahu = "\u0423\u0437\u0435\u043b \u043d\u0435 \u0434\u0430\u043b \u0434\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u0434\u043b\u044f \u044d\u0442\u043e\u0433\u043e \u0441\u0447\u0451\u0442\u0430.";
  this.agr = "\u0421\u0432\u043e\u0434\u043a\u0430 \u0443\u0437\u043b\u0430 \u043d\u0435 \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043d\u0430 \u0435\u0433\u043e \u043a\u043b\u044e\u0447\u043e\u043c.";
  this.ahV = "\u0412\u0430\u0448\u0430 \u0446\u0435\u043f\u043e\u0447\u043a\u0430 \u043d\u0435 \u0432\u0445\u043e\u0434\u0438\u0442 \u0432 \u043f\u043e\u0434\u043f\u0438\u0441\u0430\u043d\u043d\u0443\u044e \u0441\u0432\u043e\u0434\u043a\u0443 \u0443\u0437\u043b\u0430.";
  this.ag1 = "\u042d\u0442\u043e \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u043e \u043f\u043e\u0441\u0447\u0438\u0442\u0430\u043b\u043e \u0432\u0441\u0451 \u0441\u0430\u043c\u043e; \u0443 \u0443\u0437\u043b\u0430 \u0431\u044b\u043b\u0438 \u0437\u0430\u043f\u0440\u043e\u0448\u0435\u043d\u044b \u0442\u043e\u043b\u044c\u043a\u043e \u0437\u0430\u043f\u0438\u0441\u0438.";
