  this.ah6 = "\u0423\u0447\u0430\u0441\u0442\u043d\u0438\u043a";
  this.afX = "\u041a\u0440\u0435\u0434\u0438\u0442\u043d\u0430\u044f \u043b\u0438\u043d\u0438\u044f";
