  this.ajT = "\u0412\u044b\u0431\u0440\u0430\u0442\u044c";
  this.aie = "\u041e\u0442\u043a\u0440\u044b\u0442\u044c \u0438\u043b\u0438 \u0434\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0435\u0449\u0451";
