  this.ags = "\u042d\u0442\u043e\u0442 \u043a\u043b\u044e\u0447 \u0443\u0436\u0435 \u0434\u0435\u0440\u0436\u0438\u0442 \u0441\u0447\u0451\u0442.";
  this.afD = "\u0421\u0447\u0451\u0442 \u0437\u0430 \u044d\u0442\u043e \u0432\u0440\u0435\u043c\u044f \u0438\u0437\u043c\u0435\u043d\u0438\u043b\u0441\u044f. \u041f\u043e\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0435\u0449\u0451 \u0440\u0430\u0437.";
  this.ahc = "\u041f\u043b\u0430\u0442\u0451\u0436 \u0441 \u0442\u0430\u043a\u0438\u043c \u0438\u043c\u0435\u043d\u0435\u043c \u0443\u0436\u0435 \u0431\u044b\u043b \u0441\u0434\u0435\u043b\u0430\u043d.";
  this.af3 = "\u042d\u0442\u0430 \u043e\u0431\u0449\u0438\u043d\u0430 \u0441\u0430\u043c\u0430 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432: \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u0435 \u0443 \u043d\u0435\u0451 \u0441\u0447\u0451\u0442.";
  this.aib = "\u042d\u0442\u043e\u0442 \u0441\u0447\u0451\u0442 \u0443\u0436\u0435 \u043e\u0442\u043a\u0440\u044b\u0442.";
