  this.aj7 = "\u042d\u0442\u0430 \u043e\u0431\u0449\u0438\u043d\u0430 \u0443\u0436\u0435 \u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0430.";
  this.ai5 = "\u0423\u0437\u0435\u043b \u043d\u0435 \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442. \u041f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u0441\u043e\u0435\u0434\u0438\u043d\u0435\u043d\u0438\u0435 \u0438 \u043f\u043e\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0435\u0449\u0451 \u0440\u0430\u0437.";
  this.agg = "\u041d\u0430\u0439\u0434\u0438\u0442\u0435 \u0441\u0432\u043e\u044e \u043e\u0431\u0449\u0438\u043d\u0443";
  this.agh = "\u0423 \u043a\u0430\u0436\u0434\u043e\u0439 \u043e\u0431\u0449\u0438\u043d\u044b \u0441\u0432\u043e\u0439 \u0443\u0437\u0435\u043b, \u0441\u0432\u043e\u0438 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0438 \u0438 \u043f\u0440\u0430\u0432\u0438\u043b\u0430. \u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0432\u043e\u044e, \u0432\u0432\u0435\u0434\u0438\u0442\u0435 \u0430\u0434\u0440\u0435\u0441, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043e\u043d\u0430 \u0432\u0430\u043c \u0434\u0430\u043b\u0430, \u0438\u043b\u0438 \u0441\u043e\u0437\u0434\u0430\u0439\u0442\u0435 \u043d\u043e\u0432\u0443\u044e.";
  this.afN = "\u041e\u0431\u0449\u0438\u043d\u044b \u0437\u0434\u0435\u0441\u044c";
  this.ahq = "\u043f\u043e\u043a\u0430 \u043d\u0438 \u043e\u0434\u043d\u043e\u0439";
