  this.afV = "\u0421\u043e\u0437\u0434\u0430\u0442\u044c \u043e\u0431\u0449\u0438\u043d\u0443";
  this.afW = "\u0412\u044b \u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0435\u0441\u044c \u0435\u0451 \u043e\u0441\u043d\u043e\u0432\u0430\u0442\u0435\u043b\u0435\u043c: \u043a\u043b\u044e\u0447 \u0432\u0430\u0448\u0435\u0433\u043e \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430 \u043e\u0442\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0441\u0447\u0451\u0442 \u043e\u0431\u0449\u0438\u043d\u044b, \u0438 \u0441 \u043d\u0435\u0433\u043e \u0432\u044b \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442\u0435 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432 \u0438 \u0437\u0430\u0434\u0430\u0451\u0442\u0435 \u0438\u043c \u043b\u0438\u043c\u0438\u0442\u044b. \u0411\u043e\u043b\u044c\u0448\u0435 \u0435\u044e \u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442.";
  this.aiw = "\u0415\u0451 \u043c\u0435\u0441\u0442\u043e \u0432 \u0430\u0434\u0440\u0435\u0441\u0435";
