  this.agz = "\u041a\u0430\u043a \u0432\u0441\u0442\u0443\u043f\u0430\u044e\u0442";
  this.afo = "\u043f\u043e \u0432\u0430\u0448\u0435\u043c\u0443 \u0440\u0435\u0448\u0435\u043d\u0438\u044e (\u043d\u0430\u0434\u0451\u0436\u043d\u0435\u0435)";
  this.ahl = "\u041a\u0440\u0435\u0434\u0438\u0442\u043d\u0430\u044f \u043b\u0438\u043d\u0438\u044f \u043d\u043e\u0432\u0438\u0447\u043a\u0430";
  this.ahk = "\u041f\u043e\u0442\u043e\u043b\u043e\u043a \u043d\u043e\u0432\u0438\u0447\u043a\u0430";
  this.afP = "\u041e\u0431\u0449\u0438\u043d\u0430 \u0441\u043e\u0437\u0434\u0430\u043d\u0430";
  this.afQ = "\u0415\u0451 \u0441\u0447\u0451\u0442 \u2014 \u0432 \u044d\u0442\u043e\u043c \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0438. \u041f\u0440\u0438\u0433\u043b\u0430\u0448\u0430\u0439\u0442\u0435 \u043b\u044e\u0434\u0435\u0439 \u0441\u0441\u044b\u043b\u043a\u043e\u0439 \u0438\u0437 \u0440\u0430\u0437\u0434\u0435\u043b\u0430 \u00ab\u041f\u0440\u0438\u0433\u043b\u0430\u0441\u0438\u0442\u044c\u00bb \u0438 \u043e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \u0441\u0432\u043e\u0439 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0441\u0447\u0451\u0442: \u00ab\u0421\u0447\u0435\u0442\u0430\u00bb, \u0437\u0430\u0442\u0435\u043c \u00ab\u041e\u0442\u043a\u0440\u044b\u0442\u044c \u0438\u043b\u0438 \u0434\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0435\u0449\u0451\u00bb.";
  this.agG = "\u041f\u0440\u0438\u0433\u043b\u0430\u0441\u0438\u0442\u044c";
  this.agH = "\u041e\u0442\u043f\u0440\u0430\u0432\u044c\u0442\u0435 \u044d\u0442\u0443 \u0441\u0441\u044b\u043b\u043a\u0443 \u0442\u043e\u043c\u0443, \u043a\u043e\u0433\u043e \u0445\u043e\u0442\u0438\u0442\u0435 \u0432\u0438\u0434\u0435\u0442\u044c \u0432 \u043e\u0431\u0449\u0438\u043d\u0435. \u041e\u043d\u0430 \u043e\u0442\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0441\u0440\u0430\u0437\u0443 \u0432 \u044d\u0442\u043e\u0439 \u043e\u0431\u0449\u0438\u043d\u0435.";
  this.af9 = "\u0412\u044b \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u043b\u0438 \u043f\u0440\u0438\u043d\u044f\u0442\u044c \u0432\u0430\u0441";
  this.afE = "\u041f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u0435\u0449\u0451 \u0440\u0430\u0437";
  this.ak5 = "\u0417\u0430\u0431\u044b\u0442\u044c \u044d\u0442\u0443 \u0437\u0430\u044f\u0432\u043a\u0443";
  this.aiW = "\u041a\u0442\u043e \u043f\u0440\u043e\u0441\u0438\u0442 \u043f\u0440\u0438\u043d\u044f\u0442\u044c";
  this.ahw = "\u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u0436\u0434\u0451\u0442";
  this.af2 = "\u041f\u0440\u0438\u043d\u044f\u0442\u044c";
  this.aiU = "\u041e\u0442\u043a\u043b\u043e\u043d\u0438\u0442\u044c";
  this.af4 = "\u041f\u0440\u0438\u043d\u044f\u0442";
  this.aiV = "\u041e\u0442\u043a\u043b\u043e\u043d\u0435\u043d\u043e";
  this.ahG = "\u041d\u0435 \u043f\u0440\u0438\u043d\u044f\u0442";
  this.aiz = "\u042d\u0442\u043e \u043c\u0435\u0441\u0442\u043e \u0437\u0430\u043d\u044f\u0442\u043e: \u0432\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0434\u0440\u0443\u0433\u043e\u0435.";
  this.aix = "\u0412 \u043c\u0435\u0441\u0442\u0435 \u2014 \u043e\u0442 3 \u0434\u043e 40 \u0441\u0442\u0440\u043e\u0447\u043d\u044b\u0445 \u043b\u0430\u0442\u0438\u043d\u0441\u043a\u0438\u0445 \u0431\u0443\u043a\u0432, \u0446\u0438\u0444\u0440 \u0438\u043b\u0438 \u0434\u0435\u0444\u0438\u0441\u043e\u0432; \u0432 \u0435\u0434\u0438\u043d\u0438\u0446\u0435 \u2014 \u0431\u0443\u043a\u0432\u044b.";
  this.agC = "\u0421\u0435\u0433\u043e\u0434\u043d\u044f \u043e\u0442\u0441\u044e\u0434\u0430 \u0431\u043e\u043b\u044c\u0448\u0435 \u043d\u0435\u043b\u044c\u0437\u044f \u0441\u043e\u0437\u0434\u0430\u0432\u0430\u0442\u044c \u043e\u0431\u0449\u0438\u043d\u044b.";
  this.agA = "\u0417\u0434\u0435\u0441\u044c \u043e\u0431\u0449\u0438\u043d\u044b \u0441\u043e\u0437\u0434\u0430\u0451\u0442 \u043d\u0435 \u043a\u0430\u0436\u0434\u044b\u0439: \u043e\u0431\u0440\u0430\u0442\u0438\u0442\u0435\u0441\u044c \u043a \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440\u0443 \u044d\u0442\u043e\u0433\u043e \u0441\u0430\u0439\u0442\u0430.";
  this.af7 = "\u0414\u0440\u0443\u0433\u0430\u044f \u043e\u0431\u0449\u0438\u043d\u0430";
  this.ajR = "\u0415\u0434\u0438\u043d\u0438\u0446\u0430";
  this.aim = "\u0412 \u0434\u0440\u0443\u0433\u0443\u044e \u043e\u0431\u0449\u0438\u043d\u0443";
  this.ak2 = "\u0412 \u043a\u0430\u043a\u0443\u044e \u043e\u0431\u0449\u0438\u043d\u0443";
  this.ahA = "\u0412 \u0442\u043e\u0439 \u043e\u0431\u0449\u0438\u043d\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435\u043a\u043e\u043c\u0443 \u043f\u043b\u0430\u0442\u0438\u0442\u044c.";
  this.ajK = "\u041b\u0438\u043d\u0438\u0438 \u0434\u043e\u0432\u0435\u0440\u0438\u044f";
  this.agY = "\u041b\u0438\u043d\u0438\u044f \u0434\u043e\u0432\u0435\u0440\u0438\u044f \u0433\u043e\u0432\u043e\u0440\u0438\u0442, \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0434\u0440\u0443\u0433\u0430\u044f \u043e\u0431\u0449\u0438\u043d\u0430 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u0434\u043e\u043b\u0436\u043d\u0430 \u043d\u0430\u0448\u0435\u0439. \u0422\u043e\u0433\u0434\u0430 \u0435\u0451 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0438 \u043c\u043e\u0433\u0443\u0442 \u043f\u043b\u0430\u0442\u0438\u0442\u044c \u043d\u0430\u0448\u0438\u043c, \u0430 \u043d\u0430\u0448\u0438 \u2014 \u0435\u0451 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0430\u043c, \u043d\u0430\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u041e\u041d\u0410 \u0434\u043e\u0432\u0435\u0440\u044f\u0435\u0442 \u043d\u0430\u043c. \u041f\u043b\u044e\u0441 \u043d\u0430 \u0431\u0430\u043b\u0430\u043d\u0441\u0435: \u0434\u043e\u043b\u0436\u043d\u044b \u043c\u044b; \u043c\u0438\u043d\u0443\u0441: \u0434\u043e\u043b\u0436\u043d\u044b \u043d\u0430\u043c.";
  this.ajE = "\u041c\u043e\u0433\u0443\u0442 \u0431\u044b\u0442\u044c \u0434\u043e\u043b\u0436\u043d\u044b \u043d\u0430\u043c";
  this.ahs = "\u043b\u0438\u043d\u0438\u0439 \u043f\u043e\u043a\u0430 \u043d\u0435\u0442";
  this.aid = "\u041e\u0442\u043a\u0440\u044b\u0442\u044c \u043b\u0438\u043d\u0438\u044e";
  this.agS = "\u0410\u0434\u0440\u0435\u0441 \u0434\u0440\u0443\u0433\u043e\u0439 \u043e\u0431\u0449\u0438\u043d\u044b";
  this.agT = "\u043a\u0430\u043a \u0432 \u0435\u0451 \u0441\u0441\u044b\u043b\u043a\u0435-\u043f\u0440\u0438\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0438 \u043f\u043e\u0441\u043b\u0435 ?node=";
  this.afC = "\u0418\u0437\u043c\u0435\u043d\u0438\u0442\u044c";
  this.agV = "\u041b\u0438\u043d\u0438\u044f \u043e\u0442\u043a\u0440\u044b\u0442\u0430";
  this.agU = "\u041b\u0438\u043d\u0438\u044f \u043d\u0435 \u043e\u0442\u043a\u0440\u044b\u0442\u0430";
  this.agX = "\u0422\u0430 \u043e\u0431\u0449\u0438\u043d\u0430 \u0441\u0447\u0438\u0442\u0430\u0435\u0442 \u0432 \u0434\u0440\u0443\u0433\u043e\u0439 \u0435\u0434\u0438\u043d\u0438\u0446\u0435: \u043b\u0438\u043d\u0438\u0438 \u043c\u0435\u0436\u0434\u0443 \u0440\u0430\u0437\u043d\u044b\u043c\u0438 \u0435\u0434\u0438\u043d\u0438\u0446\u0430\u043c\u0438 \u0435\u0449\u0451 \u043d\u0435 \u0441\u0434\u0435\u043b\u0430\u043d\u044b.";
  this.ahz = "\u041f\u043e \u044d\u0442\u043e\u043c\u0443 \u0430\u0434\u0440\u0435\u0441\u0443 \u043e\u0431\u0449\u0438\u043d\u0430 \u043d\u0435 \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442.";
  this.agW = "\u042d\u0442\u043e \u0441\u0430\u043c\u0430 \u043d\u0430\u0448\u0430 \u043e\u0431\u0449\u0438\u043d\u0430.";
  this.ak3 = "\u041a\u0442\u043e \u043c\u043e\u0436\u0435\u0442 \u0432\u0441\u0442\u0443\u043f\u0438\u0442\u044c";
  this.afn = "\u0442\u043e\u043b\u044c\u043a\u043e \u0431\u0438\u0437\u043d\u0435\u0441\u044b \u0438 \u0441\u0430\u043c\u043e\u0437\u0430\u043d\u044f\u0442\u044b\u0435 (\u043f\u0440\u043e\u0449\u0435 \u0432\u0441\u0435\u0433\u043e)";
  this.aio = "\u0431\u0438\u0437\u043d\u0435\u0441\u044b \u0438 \u0447\u0430\u0441\u0442\u043d\u044b\u0435 \u043b\u0438\u0446\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u0437\u0430\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0442, \u043f\u043e\u0442\u043e\u043c \u0442\u0440\u0430\u0442\u044f\u0442 (\u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0443\u0435\u0442\u0441\u044f)";
  this.ain = "\u0431\u0438\u0437\u043d\u0435\u0441\u044b \u0438 \u0447\u0430\u0441\u0442\u043d\u044b\u0435 \u043b\u0438\u0446\u0430, \u0443 \u0432\u0441\u0435\u0445 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u044b\u0435 \u043b\u0438\u043d\u0438\u0438";
  this.aig = "\u0412\u0430\u0448 \u0441\u0447\u0451\u0442 \u043d\u0430\u0447\u0438\u043d\u0430\u0435\u0442\u0441\u044f \u0441 \u043d\u0443\u043b\u044f \u0438 \u043d\u0438\u0436\u0435 \u043d\u0443\u043b\u044f \u043d\u0435 \u043e\u043f\u0443\u0441\u043a\u0430\u0435\u0442\u0441\u044f. \u041f\u0440\u043e\u0434\u0430\u0439\u0442\u0435 \u0447\u0442\u043e-\u043d\u0438\u0431\u0443\u0434\u044c \u0438\u043b\u0438 \u0441\u0434\u0435\u043b\u0430\u0439\u0442\u0435 \u0440\u0430\u0431\u043e\u0442\u0443 \u0434\u043b\u044f \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0430 \u2014 \u0438 \u0442\u0440\u0430\u0442\u044c\u0442\u0435 \u0437\u0430\u0440\u0430\u0431\u043e\u0442\u0430\u043d\u043d\u043e\u0435.";
  this.ahr = "\u0423 \u0441\u0447\u0451\u0442\u0430 \u0447\u0430\u0441\u0442\u043d\u043e\u0433\u043e \u043b\u0438\u0446\u0430 \u0432 \u044d\u0442\u043e\u0439 \u043e\u0431\u0449\u0438\u043d\u0435 \u043d\u0435\u0442 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u043e\u0439 \u043b\u0438\u043d\u0438\u0438: \u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u0437\u0430\u0440\u0430\u0431\u043e\u0442\u0430\u0442\u044c, \u043f\u043e\u0442\u043e\u043c \u0442\u0440\u0430\u0442\u0438\u0442\u044c.";
  this.aj3 = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u043e\u0431\u0449\u0438\u043d\u044b";
  this.aj2 = "\u043d\u0430\u0447\u0430\u043b\u044c\u043d\u044b\u0439 \u0442\u0435\u043a\u0441\u0442: \u0435\u0433\u043e \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442 \u043a\u0430\u0436\u0434\u044b\u0439 \u043d\u043e\u0432\u0438\u0447\u043e\u043a. \u041f\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043c \u043d\u0430 \u043d\u0435\u0433\u043e \u043f\u043e\u043b\u0430\u0433\u0430\u0442\u044c\u0441\u044f, \u043f\u043e\u043a\u0430\u0436\u0438\u0442\u0435 \u0435\u0433\u043e \u044e\u0440\u0438\u0441\u0442\u0443.";
  this.ajs = "1. \u041e\u0431\u0449\u0438\u043d\u0430 \u0432\u0435\u0434\u0451\u0442 \u043e\u0431\u0449\u0438\u0439 \u0441\u0447\u0451\u0442 \u0442\u043e\u0433\u043e, \u0447\u0442\u043e \u0435\u0451 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0438 \u0434\u0430\u044e\u0442 \u0434\u0440\u0443\u0433 \u0434\u0440\u0443\u0433\u0443 \u0438 \u0431\u0435\u0440\u0443\u0442 \u0434\u0440\u0443\u0433 \u0443 \u0434\u0440\u0443\u0433\u0430. \u0415\u0434\u0438\u043d\u0438\u0446\u0430 \u2014 \u043c\u0435\u0440\u0430 \u0432 \u044d\u0442\u043e\u043c \u0441\u0447\u0451\u0442\u0435; \u0432 \u0446\u0435\u043d\u0430\u0445 \u043e\u043d\u0430 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u043e\u0434\u043d\u0430 \u0435\u0434\u0438\u043d\u0438\u0446\u0430 \u043d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0439 \u0432\u0430\u043b\u044e\u0442\u044b.\n2. \u0415\u0434\u0438\u043d\u0438\u0446\u044b \u2014 \u043d\u0435 \u0434\u0435\u043d\u044c\u0433\u0438. \u041d\u0438\u043a\u0442\u043e \u0438 \u043d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u043f\u0440\u043e\u0434\u0430\u0451\u0442, \u043d\u0435 \u043f\u043e\u043a\u0443\u043f\u0430\u0435\u0442 \u0438 \u043d\u0435 \u043e\u0431\u043c\u0435\u043d\u0438\u0432\u0430\u0435\u0442 \u0438\u0445 \u043d\u0430 \u0434\u0435\u043d\u044c\u0433\u0438.\n3. \u0411\u0430\u043b\u0430\u043d\u0441 \u0432\u044b\u0448\u0435 \u043d\u0443\u043b\u044f \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442, \u043d\u0430\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a \u0434\u0430\u043b \u0431\u043e\u043b\u044c\u0448\u0435, \u0447\u0435\u043c \u0432\u0437\u044f\u043b; \u0431\u0430\u043b\u0430\u043d\u0441 \u043d\u0438\u0436\u0435 \u043d\u0443\u043b\u044f \u2014 \u043d\u0430\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043e\u043d \u0432\u0437\u044f\u043b \u0431\u043e\u043b\u044c\u0448\u0435, \u0447\u0435\u043c \u0434\u0430\u043b, \u0438 \u0434\u043e\u043b\u0436\u0435\u043d \u0432\u0435\u0440\u043d\u0443\u0442\u044c \u043e\u0431\u0449\u0438\u043d\u0435 \u0441\u0432\u043e\u0438\u043c\u0438 \u0442\u043e\u0432\u0430\u0440\u0430\u043c\u0438 \u0438 \u0443\u0441\u043b\u0443\u0433\u0430\u043c\u0438.\n4. \u0423 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0430 \u0435\u0441\u0442\u044c \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u0430\u044f \u043b\u0438\u043d\u0438\u044f \u0438 \u043f\u043e\u0442\u043e\u043b\u043e\u043a; \u0438\u0445 \u0437\u0430\u0434\u0430\u0451\u0442 \u043e\u0431\u0449\u0438\u043d\u0430 \u0438 \u043c\u043e\u0436\u0435\u0442 \u043c\u0435\u043d\u044f\u0442\u044c.\n5. \u0423\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442 \u043e\u0431\u0449\u0438\u043d\u0430, \u0438 \u043e\u043d\u0430 \u0437\u043d\u0430\u0435\u0442 \u0438\u0445 \u043f\u043e \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0438\u043c \u0438\u043c\u0435\u043d\u0430\u043c.\n6. \u041f\u0440\u043e\u0434\u0430\u0436\u0430 \u0437\u0430 \u0435\u0434\u0438\u043d\u0438\u0446\u044b \u2014 \u044d\u0442\u043e \u043f\u0440\u043e\u0434\u0430\u0436\u0430. \u041a\u0430\u0436\u0434\u044b\u0439 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a \u0441\u0430\u043c \u0432\u044b\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u0441\u0447\u0435\u0442\u0430 \u0438 \u0441\u0430\u043c \u043f\u043b\u0430\u0442\u0438\u0442 \u043d\u0430\u043b\u043e\u0433\u0438, \u0434\u0435\u043d\u044c\u0433\u0430\u043c\u0438, \u043a\u0430\u043a \u0441 \u043b\u044e\u0431\u043e\u0439 \u043f\u0440\u043e\u0434\u0430\u0436\u0438.\n7. \u0423\u0447\u0430\u0441\u0442\u043d\u0438\u043a \u043c\u043e\u0436\u0435\u0442 \u0432\u044b\u0439\u0442\u0438 \u0432 \u043b\u044e\u0431\u043e\u0435 \u0432\u0440\u0435\u043c\u044f, \u043f\u0440\u0438\u0432\u0435\u0434\u044f \u0431\u0430\u043b\u0430\u043d\u0441 \u043a \u043d\u0443\u043b\u044e. \u0412\u044b\u0448\u0435\u0434\u0448\u0438\u0439 \u0441 \u0431\u0430\u043b\u0430\u043d\u0441\u043e\u043c \u043d\u0438\u0436\u0435 \u043d\u0443\u043b\u044f \u043f\u043e\u0433\u0430\u0448\u0430\u0435\u0442 \u0440\u0430\u0437\u043d\u0438\u0446\u0443 \u0434\u0435\u043d\u044c\u0433\u0430\u043c\u0438 \u0432 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 30 \u0434\u043d\u0435\u0439.\n8. \u041e\u0431\u0449\u0438\u043d\u0430 \u043c\u043e\u0436\u0435\u0442 \u0437\u0430\u043a\u0440\u044b\u0442\u044c \u0441\u0447\u0451\u0442 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043d\u0430\u0440\u0443\u0448\u0430\u0435\u0442 \u044d\u0442\u0438 \u043f\u0440\u0430\u0432\u0438\u043b\u0430.";
  this.aeK = "\u041f\u0440\u0438\u043d\u0438\u043c\u0430\u044e";
  this.aj0 = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430";
  this.aj4 = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u044b";
  this.aj1 = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u043e\u0431\u0449\u0438\u043d\u044b \u0438\u0437\u043c\u0435\u043d\u0438\u043b\u0438\u0441\u044c: \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u0438 \u043f\u0440\u0438\u043c\u0438\u0442\u0435 \u0438\u0445 \u0437\u0430\u043d\u043e\u0432\u043e.";
  this.ai8 = "\u042d\u0442\u0430 \u043e\u0431\u0449\u0438\u043d\u0430 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0431\u0438\u0437\u043d\u0435\u0441\u044b \u0438 \u0441\u0430\u043c\u043e\u0437\u0430\u043d\u044f\u0442\u044b\u0445.";
  this.afU = "\u0421\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432\u044b\u043f\u0438\u0441\u043a\u0443 (CSV)";
  this.ajt = "\u0421\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u043d\u043e";
  this.aju = "\u0412\u0430\u0448\u0438 \u0441\u0434\u0435\u043b\u043a\u0438 \u0432 \u0431\u0443\u0444\u0435\u0440\u0435 \u043e\u0431\u043c\u0435\u043d\u0430 \u0432 \u0432\u0438\u0434\u0435 CSV: \u0432\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u0438\u0445 \u0432 \u0442\u0430\u0431\u043b\u0438\u0446\u0443 \u0438\u043b\u0438 \u043f\u0435\u0440\u0435\u0434\u0430\u0439\u0442\u0435 \u0431\u0443\u0445\u0433\u0430\u043b\u0442\u0435\u0440\u0443. \u0421\u0434\u0435\u043b\u043a\u0430 \u0432 \u0435\u0434\u0438\u043d\u0438\u0446\u0430\u0445 \u2014 \u044d\u0442\u043e \u043f\u0440\u043e\u0434\u0430\u0436\u0430, \u043e\u043d\u0430 \u0443\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0438 \u043e\u0431\u043b\u0430\u0433\u0430\u0435\u0442\u0441\u044f \u043d\u0430\u043b\u043e\u0433\u043e\u043c \u043a\u0430\u043a \u043b\u044e\u0431\u0430\u044f \u0434\u0440\u0443\u0433\u0430\u044f.";
  this.ahJ = "\u042d\u0442\u043e\u0442 \u0431\u0440\u0430\u0443\u0437\u0435\u0440 \u043d\u0435 \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0435 \u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c. \u0412\u044b\u0434\u0435\u043b\u0438\u0442\u0435 \u0442\u0430\u0431\u043b\u0438\u0446\u0443 \u0438 \u0441\u043a\u043e\u043f\u0438\u0440\u0443\u0439\u0442\u0435 \u0432\u0440\u0443\u0447\u043d\u0443\u044e.";
  this.agZ = "\u042f \u043f\u043e\u0442\u0435\u0440\u044f\u043b(\u0430) \u0441\u0432\u043e\u0438 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430";
  this.ah0 = "\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0432\u043e\u0439 \u0441\u0447\u0451\u0442. \u042d\u0442\u043e \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u043e \u0441\u043e\u0437\u0434\u0430\u0441\u0442 \u043d\u043e\u0432\u044b\u0439 \u043a\u043b\u044e\u0447 \u0438 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442 \u0432\u0430\u0448\u0443 \u043e\u0431\u0449\u0438\u043d\u0443 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044c, \u0447\u0442\u043e \u044d\u0442\u043e \u0432\u044b. \u041f\u043e\u0441\u043b\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u044f \u043a\u043b\u044e\u0447 \u043d\u0430\u0447\u043d\u0451\u0442 \u0434\u0435\u0440\u0436\u0430\u0442\u044c \u0441\u0447\u0451\u0442 \u0447\u0435\u0440\u0435\u0437 \u043d\u0435\u0434\u0435\u043b\u044e \u2014 \u0432\u0440\u0435\u043c\u044f, \u0447\u0442\u043e\u0431\u044b \u0432\u044b \u0443\u0441\u043f\u0435\u043b\u0438 \u043e\u0442\u043a\u0430\u0437\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043f\u0440\u043e\u0441\u0438\u043b \u043a\u0442\u043e-\u0442\u043e \u0434\u0440\u0443\u0433\u043e\u0439.";
  this.agJ = "\u042d\u0442\u043e \u043c\u043e\u0439 \u0441\u0447\u0451\u0442";
  this.afa = "\u0412\u044b \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u043b\u0438 \u0432\u0435\u0440\u043d\u0443\u0442\u044c \u0441\u0447\u0451\u0442";
  this.ahZ = "\u0415\u0449\u0451 \u043d\u0435\u0442: \u0441\u0440\u043e\u043a \u043e\u0436\u0438\u0434\u0430\u043d\u0438\u044f \u043d\u0435 \u043f\u0440\u043e\u0448\u0451\u043b.";
  this.aff = "\u041f\u0440\u0438\u043d\u044f\u0442\u044c \u0441\u0447\u0451\u0442";
  this.agl = "\u0417\u0430\u0431\u044b\u0442\u044c";
  this.afv = "\u042d\u0442\u043e \u043d\u0435 \u044f: \u043e\u0442\u043c\u0435\u043d\u0438\u0442\u044c";
  this.aiS = "\u041e\u0442\u043c\u0435\u043d\u0435\u043d\u043e: \u0442\u043e \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u043e \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043f\u043e\u043b\u0443\u0447\u0438\u0442.";
  this.aiQ = "\u041a\u0442\u043e \u043f\u0440\u043e\u0441\u0438\u0442 \u0432\u0435\u0440\u043d\u0443\u0442\u044c \u0441\u0447\u0451\u0442";
  this.aiP = "\u041f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0439\u0442\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u0443\u0432\u0435\u0440\u0435\u043d\u044b, \u0447\u0442\u043e \u044d\u0442\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a: \u043f\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0435 \u0441 \u043d\u0438\u043c, \u043d\u0435 \u0432\u0435\u0440\u044c\u0442\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u044e. \u0421\u0442\u0430\u0440\u044b\u0435 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430 \u0441\u0447\u0451\u0442\u0430 \u0435\u0449\u0451 \u043d\u0435\u0434\u0435\u043b\u044e \u043c\u043e\u0433\u0443\u0442 \u043e\u0442\u043c\u0435\u043d\u0438\u0442\u044c.";
  this.ahv = "\u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u043f\u0440\u043e\u0441\u0438\u0442";
  this.afS = "\u042d\u0442\u043e \u043e\u043d(\u0430): \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044c";
  this.aiR = "\u041e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u043e";
  this.ag2 = "\u041d\u0435 \u043e\u043d(\u0430): \u043e\u0442\u043a\u043b\u043e\u043d\u0438\u0442\u044c";
  this.afh = "\u0414\u043e\u0441\u043a\u0430";
  this.afl = "\u0427\u0442\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0438 \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u044e\u0442 \u0438 \u0447\u0442\u043e \u0438\u0449\u0443\u0442. \u0426\u0435\u043d\u0430 \u2014 \u0432 \u043d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0439 \u0432\u0430\u043b\u044e\u0442\u0435; \u0434\u043e\u043b\u044f \u0433\u043e\u0432\u043e\u0440\u0438\u0442, \u043a\u0430\u043a\u0430\u044f \u0435\u0451 \u0447\u0430\u0441\u0442\u044c \u0431\u0435\u0440\u0451\u0442\u0441\u044f \u0435\u0434\u0438\u043d\u0438\u0446\u0430\u043c\u0438, \u2014 \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u043e\u0435 \u043f\u043b\u0430\u0442\u0438\u0442\u0441\u044f \u0434\u0435\u043d\u044c\u0433\u0430\u043c\u0438, \u0432\u043d\u0435 \u0441\u0438\u0441\u0442\u0435\u043c\u044b.";
  this.afk = "\u0412\u0438\u0434";
  this.ai4 = "\u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u0435\u0442";
  this.ak0 = "\u0438\u0449\u0435\u0442";
  this.afi = "\u043f\u043e\u043a\u0430 \u043f\u0443\u0441\u0442\u043e: \u0431\u0443\u0434\u044c\u0442\u0435 \u043f\u0435\u0440\u0432\u044b\u043c";
  this.aic = "\u041e\u0442\u043a\u0440\u044b\u0442\u044c";
  this.aeW = "\u041f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u044e";
  this.aeZ = "\u0418\u0449\u0443";
  this.agf = "\u041f\u043e\u0434\u0440\u043e\u0431\u043d\u0435\u0435";
  this.aiI = "\u0426\u0435\u043d\u0430";
  this.aiJ = "\u043e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u043f\u0443\u0441\u0442\u044b\u043c: \u043f\u043e \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0451\u043d\u043d\u043e\u0441\u0442\u0438";
  this.afp = "\u043f\u043e \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0451\u043d\u043d\u043e\u0441\u0442\u0438";
  this.agE = "\u0415\u0434\u0438\u043d\u0438\u0446\u0430\u043c\u0438, %";
  this.agF = "\u043a\u0430\u043a\u0443\u044e \u0434\u043e\u043b\u044e \u0446\u0435\u043d\u044b \u0432\u044b \u0431\u0435\u0440\u0451\u0442\u0435 \u0438\u043b\u0438 \u043f\u043b\u0430\u0442\u0438\u0442\u0435 \u0435\u0434\u0438\u043d\u0438\u0446\u0430\u043c\u0438: 100 \u2014 \u0432\u0441\u044e, 50 \u2014 \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0443";
  this.ajd = "\u043e\u0442 0 \u0434\u043e 100";
  this.aiH = "\u041e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u0438\u0435 \u043d\u0430 \u0434\u043e\u0441\u043a\u0435";
  this.ahQ = "\u041d\u0435 \u043f\u043e\u043b\u0443\u0447\u0438\u043b\u043e\u0441\u044c";
  this.afj = "\u041d\u0430 \u0434\u043e\u0441\u043a\u0435 \u043d\u0435\u0442 \u043c\u0435\u0441\u0442\u0430 \u0434\u043b\u044f \u0435\u0449\u0451 \u043e\u0434\u043d\u043e\u0433\u043e \u0432\u0430\u0448\u0435\u0433\u043e \u043e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u0438\u044f: \u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u0441\u043d\u0438\u043c\u0438\u0442\u0435 \u043e\u0434\u043d\u043e.";
  this.ajB = "\u0421\u043d\u044f\u0442\u044c \u0441 \u0434\u043e\u0441\u043a\u0438";
  this.aje = "\u041e\u0431\u0449\u0438\u0435 \u0441\u0447\u0435\u0442\u0430";
  this.ajk = "\u0421\u0447\u0451\u0442 \u0441\u0435\u043c\u044c\u0438 \u0438\u043b\u0438 \u043a\u043e\u043c\u0430\u043d\u0434\u044b \u0434\u0435\u0440\u0436\u0430\u0442 \u0441\u0447\u0435\u0442\u0430 \u0435\u0451 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432, \u0430 \u043d\u0435 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430: \u043a\u0430\u0436\u0434\u044b\u0439 \u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044c \u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u0438\u043c \u0441 \u043b\u044e\u0431\u043e\u0433\u043e \u0441\u0432\u043e\u0435\u0433\u043e \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430, \u0430 \u043f\u043e\u0442\u0435\u0440\u044f\u043d\u043d\u044b\u0439 \u0442\u0435\u043b\u0435\u0444\u043e\u043d \u0437\u0430\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u043e\u0434\u0438\u043d \u0440\u0430\u0437 \u2014 \u0432 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u043c \u0441\u0447\u0451\u0442\u0435 \u0447\u0435\u043b\u043e\u0432\u0435\u043a\u0430.";
  this.ahx = "\u043e\u0431\u0449\u0438\u0445 \u0441\u0447\u0435\u0442\u043e\u0432 \u043f\u043e\u043a\u0430 \u043d\u0435\u0442";
  this.ahj = "\u041d\u043e\u0432\u044b\u0439 \u043e\u0431\u0449\u0438\u0439 \u0441\u0447\u0451\u0442";
  this.ajg = "\u041d\u0430\u0437\u0432\u0430\u043d\u0438\u0435";
  this.ajh = "\u0421\u043d\u0430\u0447\u0430\u043b\u0430 \u043e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 \u0441\u0432\u043e\u0439 \u0441\u0447\u0451\u0442: \u043e\u0431\u0449\u0438\u0439 \u0441\u0447\u0451\u0442 \u0434\u0435\u0440\u0436\u0430\u0442 \u0441\u0447\u0435\u0442\u0430 \u0435\u0433\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432.";
  this.ajj = "\u0421\u0447\u0451\u0442 \u043e\u0442\u043a\u0440\u044b\u0442, \u0432\u044b \u0435\u0433\u043e \u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044c. \u0421\u0432\u043e\u0435\u0439 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u043e\u0439 \u043b\u0438\u043d\u0438\u0438 \u0443 \u043d\u0435\u0433\u043e \u043d\u0435\u0442: \u043e\u043d \u0442\u0440\u0430\u0442\u0438\u0442 \u0442\u043e, \u0447\u0442\u043e \u0435\u043c\u0443 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u043b\u0438, \u0438\u043b\u0438 \u043b\u0438\u043d\u0438\u044e, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u0435\u043c\u0443 \u043e\u0434\u043e\u043b\u0436\u0438\u043b \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a. \u041e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0445 \u0434\u043e\u0431\u0430\u0432\u044c\u0442\u0435 \u0432 \u0440\u0430\u0437\u0434\u0435\u043b\u0435 \u00ab\u0414\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u0438\u00bb.";
  this.agv = "\u0414\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u0438";
  this.agw = "\u041a\u0442\u043e \u043c\u043e\u0436\u0435\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c \u043e\u0442 \u0438\u043c\u0435\u043d\u0438 \u044d\u0442\u043e\u0433\u043e \u0441\u0447\u0451\u0442\u0430: \u0441\u0447\u0435\u0442\u0430 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432, \u0443 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u2014 \u0447\u0442\u043e \u043e\u043d \u043c\u043e\u0436\u0435\u0442 \u0438 \u0441\u043a\u043e\u043b\u044c\u043a\u043e. \u0414\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044c \u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u0441\u0447\u0451\u0442\u043e\u043c \u0441 \u043b\u044e\u0431\u043e\u0433\u043e \u0441\u0432\u043e\u0435\u0433\u043e \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430.";
  this.aeV = "\u0414\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044f";
  this.agu = "\u0423\u0447\u0430\u0441\u0442\u043d\u0438\u043a";
  this.ak7 = "\u0432\u044b";
  this.ajN = "\u0414\u0432\u0435 \u043f\u043e\u0434\u043f\u0438\u0441\u0438";
  this.ajL = "\u0414\u0432\u0430 \u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044f \u0434\u043b\u044f \u043f\u043b\u0430\u0442\u0435\u0436\u0430 \u0441\u0432\u044b\u0448\u0435";
  this.ajM = "\u043e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u043f\u0443\u0441\u0442\u044b\u043c: \u0434\u043b\u044f \u043b\u044e\u0431\u043e\u0433\u043e \u043f\u043b\u0430\u0442\u0435\u0436\u0430 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u043e\u0434\u043d\u043e\u0433\u043e \u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044f";
  this.ajP = "\u0423\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043e";
  this.ajO = "\u0422\u0435\u043f\u0435\u0440\u044c \u0434\u043b\u044f \u043b\u044e\u0431\u043e\u0433\u043e \u043f\u043b\u0430\u0442\u0435\u0436\u0430 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u043e\u0434\u043d\u043e\u0433\u043e \u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044f.";
  this.ajJ = "\u041f\u043b\u0430\u0442\u0435\u0436\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0436\u0434\u0443\u0442 \u0432\u0442\u043e\u0440\u043e\u0433\u043e \u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044f";
  this.ajI = "\u041f\u043b\u0430\u0442\u0451\u0436 \u0441\u0432\u044b\u0448\u0435 \u043f\u043e\u0440\u043e\u0433\u0430 \u0441\u0447\u0451\u0442\u0430 \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u0435\u0442 \u043e\u0434\u0438\u043d \u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044c, \u0430 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442 \u0434\u0440\u0443\u0433\u043e\u0439. \u041d\u0435\u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043d\u043d\u044b\u0439 \u0437\u0430 \u043d\u0435\u0434\u0435\u043b\u044e \u043f\u043b\u0430\u0442\u0451\u0436 \u043e\u0442\u043f\u0430\u0434\u0430\u0435\u0442.";
  this.ai2 = "\u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0436\u0434\u0451\u0442";
  this.afT = "\u041f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044c \u0438 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u0442\u044c";
  this.aiL = "\u041f\u0440\u0435\u0434\u043b\u043e\u0436\u0438\u043b";
  this.aiK = "\u041f\u043b\u0430\u0442\u0451\u0436 \u0436\u0434\u0451\u0442 \u0432\u0442\u043e\u0440\u043e\u0433\u043e \u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044f";
  this.ahd = "\u042d\u0442\u043e\u0442 \u043f\u043b\u0430\u0442\u0451\u0436 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0438\u043b\u0438 \u0432\u044b: \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044c \u0435\u0433\u043e \u0434\u043e\u043b\u0436\u0435\u043d \u0434\u0440\u0443\u0433\u043e\u0439 \u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044c.";
  this.ahe = "\u042d\u0442\u043e\u043c\u0443 \u043f\u043b\u0430\u0442\u0435\u0436\u0443 \u043d\u0443\u0436\u0435\u043d \u0432\u0442\u043e\u0440\u043e\u0439 \u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044c.";
  this.aiA = "\u041f\u043e\u043b\u0438\u0442\u0438\u043a\u0430";
  this.aiG = "\u0421\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u0430\u044f \u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 \u043e\u0431\u0449\u0438\u043d\u044b: \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u0441 \u043c\u043e\u043c\u0435\u043d\u0442\u0430 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u044f \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0441\u0447\u0451\u0442\u0430. \u041b\u0438\u043d\u0438\u0438, \u0432\u044b\u0434\u0430\u043d\u043d\u044b\u0435 \u0440\u0430\u043d\u044c\u0448\u0435, \u043e\u0441\u0442\u0430\u044e\u0442\u0441\u044f \u043a\u0430\u043a \u0435\u0441\u0442\u044c. \u0425\u0430\u0431, \u043d\u0430 \u043a\u043e\u0442\u043e\u0440\u043e\u043c \u0441\u0442\u043e\u0438\u0442 \u043e\u0431\u0449\u0438\u043d\u0430, \u043c\u043e\u0436\u0435\u0442 \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0442\u044c \u043c\u0435\u043d\u044c\u0448\u0435, \u0447\u0435\u043c \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u044e\u0442 \u0432 \u0434\u0440\u0443\u0433\u0438\u0445 \u043c\u0435\u0441\u0442\u0430\u0445.";
  this.aiC = "\u0412\u0441\u0442\u0443\u043f\u043b\u0435\u043d\u0438\u0435 \u0438 \u0431\u0438\u0437\u043d\u0435\u0441\u044b";
  this.aiD = "\u0427\u0430\u0441\u0442\u043d\u044b\u0435 \u043b\u0438\u0446\u0430";
  this.aiE = "\u041a\u0440\u0435\u0434\u0438\u0442 \u0447\u0430\u0441\u0442\u043d\u043e\u043c\u0443 \u043b\u0438\u0446\u0443, \u0434\u0430\u0436\u0435 \u0431\u0435\u0441\u043f\u0440\u043e\u0446\u0435\u043d\u0442\u043d\u044b\u0439, \u043c\u043e\u0436\u0435\u0442 \u043f\u043e\u0434\u043f\u0430\u0434\u0430\u0442\u044c \u043f\u043e\u0434 \u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u043f\u043e\u0442\u0440\u0435\u0431\u0438\u0442\u0435\u043b\u044c\u0441\u043a\u043e\u0433\u043e \u043a\u0440\u0435\u0434\u0438\u0442\u0430. \u0413\u0434\u0435 \u043b\u044e\u0434\u0438 \u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u0437\u0430\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0442, \u0430 \u043f\u043e\u0442\u043e\u043c \u0442\u0440\u0430\u0442\u044f\u0442, \u043a\u0440\u0435\u0434\u0438\u0442 \u043d\u0435 \u0432\u044b\u0434\u0430\u0451\u0442\u0441\u044f \u0438 \u0432\u043e\u043f\u0440\u043e\u0441 \u043d\u0435 \u0432\u043e\u0437\u043d\u0438\u043a\u0430\u0435\u0442.";
  this.aiq = "\u0431\u0438\u0437\u043d\u0435\u0441\u044b \u0438 \u0447\u0430\u0441\u0442\u043d\u044b\u0435 \u043b\u0438\u0446\u0430 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0441 \u043b\u0438\u043d\u0438\u0435\u0439, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u043e\u0434\u043e\u043b\u0436\u0438\u043b \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a";
  this.aip = "\u0431\u0438\u0437\u043d\u0435\u0441\u044b \u0438 \u0447\u0430\u0441\u0442\u043d\u044b\u0435 \u043b\u0438\u0446\u0430 \u2014 \u043b\u0438\u043d\u0438\u044f \u043f\u043e\u0441\u043b\u0435 \u0442\u043e\u0433\u043e, \u043a\u0430\u043a \u0447\u0435\u043b\u043e\u0432\u0435\u043a \u0437\u0430\u0440\u0430\u0431\u043e\u0442\u0430\u043b";
  this.air = "\u041a\u0440\u0435\u0434\u0438\u0442\u043d\u0430\u044f \u043b\u0438\u043d\u0438\u044f \u043d\u043e\u0432\u043e\u0433\u043e \u0447\u0430\u0441\u0442\u043d\u043e\u0433\u043e \u043b\u0438\u0446\u0430";
  this.ais = "\u0442\u0430\u043c, \u0433\u0434\u0435 \u0443 \u0447\u0430\u0441\u0442\u043d\u044b\u0445 \u043b\u0438\u0446 \u043b\u0438\u043d\u0438\u0438 \u0441 \u0441\u0430\u043c\u043e\u0433\u043e \u043d\u0430\u0447\u0430\u043b\u0430";
  this.ait = "\u0421\u043a\u043e\u043b\u044c\u043a\u043e \u0441\u0430\u043c\u043e\u0435 \u0431\u043e\u043b\u044c\u0448\u0435\u0435 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u0434\u043e\u043b\u0436\u0435\u043d \u0447\u0435\u043b\u043e\u0432\u0435\u043a";
  this.aiu = "\u0441\u0432\u043e\u044f \u043b\u0438\u043d\u0438\u044f \u0438 \u043e\u0434\u043e\u043b\u0436\u0435\u043d\u043d\u0430\u044f \u0432\u043c\u0435\u0441\u0442\u0435; \u043e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u043f\u0443\u0441\u0442\u044b\u043c: \u0431\u0435\u0437 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f";
  this.aho = "\u0431\u0435\u0437 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f";
  this.ag3 = "\u0417\u0430\u0440\u0430\u0431\u043e\u0442\u0430\u043d\u043e \u0434\u043e \u0432\u044b\u0434\u0430\u0447\u0438 \u043b\u0438\u043d\u0438\u0438";
