  this.anC = "\u0412\u0456\u0434\u043a\u0440\u0438\u0442\u0438";
  this.akm = "\u041f\u0440\u043e\u043f\u043e\u043d\u0443\u044e";
  this.akp = "\u0428\u0443\u043a\u0430\u044e";
  this.alF = "\u0414\u043e\u043a\u043b\u0430\u0434\u043d\u0456\u0448\u0435";
